<?php
namespace App\services;
use App\config\Database;
use App\utils\Logger;
final class MaintenanceService {
    public function run():array{$pdo=Database::get();$stats=['sessions'=>0,'password_resets'=>0,'email_verifications'=>0,'rate_limits'=>0,'proposals'=>0,'generated_media'=>0,'free_cycles'=>0,'logs'=>0];$stats['sessions']=$pdo->exec('DELETE FROM auth_sessions WHERE expires_at<NOW()');$stats['password_resets']=$pdo->exec('DELETE FROM password_resets WHERE expires_at<NOW() OR used_at IS NOT NULL');$stats['email_verifications']=$pdo->exec('DELETE FROM email_verifications WHERE expires_at<NOW() OR used_at IS NOT NULL');$stats['rate_limits']=$pdo->exec('DELETE FROM rate_limits WHERE expires_at<NOW()');try{$expired=$pdo->query('SELECT id,storage_path FROM proposal_documents WHERE expires_at<NOW()')->fetchAll();foreach($expired as $proposal){$path=dirname(__DIR__).'/storage/'.ltrim((string)$proposal['storage_path'],'/');if(is_file($path))@unlink($path);}$stats['proposals']=$pdo->exec('DELETE FROM proposal_documents WHERE expires_at<NOW()');}catch(\Throwable){}
        try{$expiredMedia=$pdo->query('SELECT id,storage_path FROM generated_media_assets WHERE expires_at<NOW()')->fetchAll();foreach($expiredMedia as $asset){$path=dirname(__DIR__).'/storage/'.ltrim((string)$asset['storage_path'],'/');if(is_file($path))@unlink($path);}$stats['generated_media']=$pdo->exec('DELETE FROM generated_media_assets WHERE expires_at<NOW()');}catch(\Throwable){}
        $q=$pdo->query("SELECT s.id,s.user_id,s.plan_id,p.credits,p.duration_days FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.provider='internal' AND s.status='active' AND s.current_period_end IS NOT NULL AND s.current_period_end<=NOW()");foreach($q->fetchAll() as $sub){$pdo->beginTransaction();try{$b=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$b->execute([$sub['user_id']]);$old=(int)$b->fetchColumn();if($old>0)$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'expiration',?,0,'Expiração do ciclo anterior','subscription_cycle',?,'confirmed',NOW())")->execute([$sub['user_id'],$old,(string)$sub['id']]);$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([(int)$sub['credits'],$sub['user_id']]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'credit',?,?, 'Créditos do novo ciclo', 'subscription_cycle',?,'confirmed',NOW())")->execute([$sub['user_id'],$sub['credits'],$sub['credits'],(string)$sub['id']]);$pdo->prepare('UPDATE subscriptions SET current_period_start=NOW(),current_period_end=DATE_ADD(NOW(),INTERVAL ? DAY),last_credits_granted_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$sub['duration_days'],$sub['id']]);$pdo->commit();$stats['free_cycles']++;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Logger::write('errors','maintenance_free_cycle',['subscription_id'=>$sub['id'],'error'=>$e->getMessage()]);}}
        $days=max(1,(int)env('LOG_RETENTION_DAYS','30'));$dir=dirname(__DIR__).'/storage/logs';$cut=time()-$days*86400;foreach(glob($dir.'/*.log')?:[] as $file){if(filemtime($file)<$cut&&@unlink($file))$stats['logs']++;}Logger::write('maintenance','completed',$stats);return $stats;}
}
